export const k: Kernel = namespaced(module, { ...SIGNATURES, ...OWN })
export const ext: Any = k.ext

// `a__b` is `b` of the submodule `a`; `Enum_VALUE` (a number) is `VALUE` of the enum `Enum`.
// Functions with a signature take Python's defaults and keywords; every function restores the
// stack when it throws (see `restoring`).
function namespaced(m: Any, signatures: Record<string, Signature>): Kernel {
  const out: Kernel = {}
  for (const name of Object.keys(m)) {
    const value = m[name]
    const sub = name.indexOf('__')
    if (sub > 0 && typeof value === 'function') {
      const [space, fn] = [name.slice(0, sub), name.slice(sub + 2)]
      const sig = signatures[`${space}.${fn}`]
      const call = restoring(m, value)
      ;(out[space] ??= {})[fn] = sig ? keywords(`${space}.${fn}`, call, sig) : call
      continue
    }
    const e = /^([A-Z][A-Za-z0-9]*[a-z][A-Za-z0-9]*)_([A-Z][A-Z0-9_]*)$/.exec(name)
    if (e && typeof value === 'number') {
      ;(out[e[1]] ??= {})[e[2]] = value
      continue
    }
    if (typeof value !== 'function') {
      out[name] = value
      continue
    }
    const sig = signatures[name]
    const call = restoring(m, value)
    out[name] = sig ? keywords(name, call, sig) : call
  }
  return out
}

/**
 * `fn` that puts the module's stack pointer back where it was when the call throws. A kernel
 * error leaves the module as a JavaScript exception, and a trap stops it; neither returns
 * through the call's own code, which would have released its stack (embind does that only for
 * some calls). Without this every failure kept 16 to 900 bytes of the 4 MB stack (a trap
 * several KB), and failures are normal: a raycast tries every face, operations retry. After
 * about 240,000 failures every call failed.
 */
function restoring(m: Any, fn: (...args: Any[]) => Any): (...args: Any[]) => Any {
  return (...args: Any[]) => {
    const sp = m.stackSave()
    try {
      return fn(...args)
    } catch (e) {
      m.stackRestore(sp)
      throw e
    }
  }
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
  if (v === null || typeof v !== 'object') return false
  const proto = Object.getPrototypeOf(v)
  // (also an object literal of another realm, whose Object.prototype is another: from an iframe,
  // node:vm or a test runner; not an instance of a class, such as a Vector, or an array)
  return proto === null || (Object.getPrototypeOf(proto) === null && Object.prototype.toString.call(v) === '[object Object]')
}

/**
 * `fn` taking Python's defaults and keywords: a trailing plain object whose keys all name
 * parameters (from its position on) gives those by name; parameters left out take their
 * defaults. (An object that is an argument itself, such as a deformation's spec, has keys
 * that are no parameter names, and is passed as it is.)
 */
function keywords(name: string, fn: (...args: Any[]) => Any, sig: Signature): (...args: Any[]) => Any {
  const names = sig.map((p) => (typeof p === 'string' ? p : p[0]))
  const required = (i: number) => typeof sig[i] === 'string'
  const fallback = (i: number) => (sig[i] as readonly [string, unknown])[1]
  return (...args: Any[]) => {
    let given = args
    let named: Record<string, unknown> | null = null
    const last = args[args.length - 1]
    if (args.length > 0 && isPlainObject(last)) {
      const keys = Object.keys(last)
      const from = args.length - 1
      if (keys.length > 0 && keys.every((key) => names.indexOf(key) >= from)) {
        named = last
        given = args.slice(0, -1)
      }
    }
    if (given.length >= names.length && !named) return fn(...given)
    if (given.length > names.length) throw new TypeError(`${name}: takes ${names.length} arguments, got ${given.length}`)
    const full = given.slice()
    for (let i = given.length; i < names.length; i++) {
      if (named && names[i] in named) full.push(named[names[i]])
      else if (!required(i)) full.push(fallback(i))
      else throw new TypeError(`${name}: missing argument ${names[i]}`)
    }
    return fn(...full)
  }
}

// -------------------------------------------------------------------------------- errors
/** A modeling operation cannot be done (for example a fillet radius that does not fit). */
export class ModelingError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'ModelingError'
  }
}

/**
 * An SMLib operation failed.
 *
 * `operation` names the smlibwasm call, `status` the kernel status code (e.g.
 * `SM_ERR_INVALID_INPUT`) and `hint` a suggestion when one is known.
 */
export class KernelError extends ModelingError {
  readonly operation: string
  readonly status: string | null
  readonly detail: string
  readonly hint: string | null

  constructor(operation: string, detail: string, status: string | null = null, hint: string | null = null) {
    let msg = `${operation} failed`
    if (status) msg += ` (${status})`
    if (hint) msg += `: ${hint}`
    super(msg)
    this.name = 'KernelError'
    this.operation = operation
    this.status = status
    this.detail = detail
    this.hint = hint
  }
}

const STATUS_RE = /(SM_[A-Z0-9_]+)/

/**
 * A failure of the kernel: what the module throws for a kernel call that fails (a plain Error,
 * or one it names, such as TessellationError), and a ModelingError (as Python's RuntimeError
 * covers both). Errors of JavaScript itself (TypeError, RangeError) and of the module's bindings
 * (wrong arguments) are not.
 */
export function _isRuntimeError(e: unknown): e is Error {
  if (e instanceof ModelingError || _isTrap(e)) return true
  if (!(e instanceof Error) || Object.getPrototypeOf(e) !== Error.prototype) return false
  return e.name === 'Error' || e.name.endsWith('Error') && !['TypeError', 'RangeError', 'ReferenceError', 'SyntaxError', 'BindingError', 'InternalError'].includes(e.name)
}

/**
 * A trap of the WebAssembly module: the kernel crashed (read memory it should not have, called
 * through a broken pointer). Natively such kernel defects mostly go unnoticed and the operation
 * fails or returns a broken body; here the call stops. The module stays usable (what the call had
 * allocated is lost), so a trap is a failed kernel call.
 */
function _isTrap(e: unknown): boolean {
  return typeof WebAssembly !== 'undefined' && e instanceof WebAssembly.RuntimeError
}

/** Runs `fn`; a failure of the kernel becomes a KernelError with context. */
export function kernelCall<T>(operation: string, fn: () => T, hint: string | null = null): T {
  try {
    return fn()
  } catch (e) {
    if (e instanceof KernelError || !_isRuntimeError(e)) throw e
    const text = _isTrap(e) ? `the kernel crashed (${(e as Error).message})` : (e as Error).message
    const m = STATUS_RE.exec(text)
    const error = new KernelError(operation, text, m ? m[1] : null, hint)
    ;(error as Any).cause = e
    throw error
  }
}

// -------------------------------------------------------------------------------- handles
// What is freed once a handle is garbage collected: the kernel object's kind and number (never
// the handle itself, which would keep it alive).
const freed = new FinalizationRegistry<[string, number]>(([kind, p]) => {
  try {
    free(kind, p)
  } catch {
    // (the module may be gone)
  }
})

function free(kind: string, p: number): void {
  if (kind === 'brep') ext.delete_brep(p)
  else if (kind === 'curve') ext.delete_curve(p)
  else if (kind === 'surface') ext.delete_surface(p)
  else if (kind === 'poly') ext.delete_polybrep(p)
}

let handles = 0

abstract class Handle {
  protected _p: number
  private readonly _kind: string

  constructor(kind: string, p: number) {
    this._kind = kind
    this._p = p
    if (p) freed.register(this, [kind, p], this)
  }

  /** A number that tells handles apart for as long as they live (their kernel objects' numbers
   * can be reused once freed). */
  readonly id: number = ++handles

  /** Gives the kernel object to a new owner: this handle no longer frees it. */
  release(): number {
    const p = this._p
    if (!p) throw new Error('the kernel object was disposed')
    this._p = 0
    freed.unregister(this)
    return p
  }

  /** False once the kernel object was disposed (or given to a new owner). */
  get alive(): boolean {
    return this._p !== 0
  }

  /** Frees the kernel object now (it is freed on garbage collection otherwise). */
  dispose(): void {
    const p = this._p
    if (!p) return
    this._p = 0
    freed.unregister(this)
    free(this._kind, p)
  }

  [Symbol.dispose](): void {
    this.dispose()
  }
}

/**
 * The error for an object used after `dispose()` freed it: a TypeError, as JavaScript's own for a
 * detached buffer, which kernelCall passes on as it is (it is no failure of the kernel).
 */
export function _disposed(what: string): TypeError {
  return new TypeError(`the ${what} was disposed: dispose() freed it in the kernel, so it cannot be used any more`)
}

/**
 * Owns one kernel Brep and frees it with the last reference. `sound` records how far the body was
 * found a sound solid (0: not checked; the levels are in shapes.ts), `props` its integrated mass
 * properties (a body's Brep does not change once wrapped).
 */
export class BrepHandle extends Handle {
  sound = 0
  props: Any = null

  constructor(brep: number) {
    if (!brep) throw new KernelError('kernel', 'operation returned no body')
    super('brep', brep)
  }

  get brep(): number {
    if (!this._p) throw _disposed('body')
    return this._p
  }
}

/** Owns one standalone kernel curve. */
export class CurveHandle extends Handle {
  constructor(curve: number) {
    if (!curve) throw new KernelError('kernel', 'operation returned no curve')
    super('curve', curve)
  }

  get curve(): number {
    if (!this._p) throw _disposed('curve')
    return this._p
  }
}

/** Owns one standalone kernel surface. */
export class SurfaceHandle extends Handle {
  constructor(surface: number) {
    if (!surface) throw new KernelError('kernel', 'operation returned no surface')
    super('surface', surface)
  }

  get surface(): number {
    if (!this._p) throw _disposed('surface')
    return this._p
  }
}

/** Owns one kernel PolyBrep (triangle mesh). */
export class PolyHandle extends Handle {
  constructor(poly: number) {
    super('poly', poly)
  }

  /** The mesh, or 0 once disposed. */
  get poly(): number {
    return this._p
  }
}

// -------------------------------------------------------------------------------- warnings
let warningHandler: (message: string) => void = (message) => console.warn(message)

/** Where smlibwasm's warnings go (Python's warnings.warn): `console.warn` unless set here. */
export function setWarningHandler(handler: (message: string) => void): void {
  warningHandler = handler
}

export function _warn(message: string): void {
  warningHandler(message)
}

// -------------------------------------------------------------------------------- options
/**
 * Checks the options object of the public function `name` as Python checks keyword arguments,
 * with a TypeError: it is a plain object (or left out), and every key is an option of `name`
 * (OPTIONS, made from smlibpy's signatures; a name that is not there takes none). Keys that start
 * with _ are smlibwasm's own. `count`, the number of arguments given (`arguments.length`), also
 * checks that there are no more than the positional parameters and the options.
 */
export function _opts(name: string, options: unknown, count = -1): void {
  const [positional, keys] = OPTIONS[name] ?? [-1, []]
  const takes = (given: number) =>
    `${name}() takes ${positional} positional argument${positional === 1 ? '' : 's'} but ${given} ${given === 1 ? 'was' : 'were'} given`
  if (options != null && !isPlainObject(options)) {
    if (positional >= 0) throw new TypeError(takes(Math.max(count, positional + 1)))
    throw new TypeError(`${name}(): the options must be an object, not ${typeof options}`)
  }
  if (positional >= 0 && count > positional + 1) throw new TypeError(takes(options == null ? count : count - 1))
  if (options == null) return
  for (const key of Object.keys(options)) {
    if (key.startsWith('_') || keys.includes(key)) continue
    let hint: string
    const camel = key.replace(/_([a-z0-9])/g, (_, c: string) => c.toUpperCase())
    const near = keys
      .map((k) => [_distance(k.toLowerCase(), key.toLowerCase()), k] as const)
      .filter(([d, k]) => d <= Math.floor((k.length + 3) / 4))
      .sort((x, y) => x[0] - y[0])
    if (keys.includes(camel)) hint = `; did you mean '${camel}'? (the options are camelCase)`
    else if (near.length) hint = `; did you mean '${near[0][1]}'?`
    else if (keys.length) hint = ` (its options: ${keys.join(', ')})`
    else hint = ' (it takes no options)'
    throw new TypeError(`${name}() got an unexpected option '${key}'${hint}`)
  }
}

/** The edit distance of two words (insertions, deletions, substitutions). */
function _distance(a: string, b: string): number {
  let row = Array.from({ length: b.length + 1 }, (_, j) => j)
  for (let i = 1; i <= a.length; i++) {
    const next = [i]
    for (let j = 1; j <= b.length; j++) next.push(Math.min(row[j] + 1, next[j - 1] + 1, row[j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1)))
    row = next
  }
  return row[b.length]
}
